function trajectories = simulateSurfaceTrajectories(opts)
    import membrane_tracking.curved_miet.*

    nMolecules = opts.nMolecules;
    nFrames = opts.nFrames;
    positionsXY = zeros(nMolecules, 2, nFrames);
    boundaryHit = false(nMolecules, nFrames);

    if isempty(opts.initialPositionsUm)
        if nMolecules == 1
            positionsXY(:,:,1) = [0 0];
        else
            radius = 0.45 * opts.membraneRadiusUm * sqrt(rand(nMolecules,1));
            angle = 2*pi*rand(nMolecules,1);
            positionsXY(:,:,1) = [radius.*cos(angle), radius.*sin(angle)];
        end
    else
        initial = double(opts.initialPositionsUm);
        if ~isequal(size(initial), [nMolecules 2]) || ...
                any(~isfinite(initial(:))) || ~isreal(initial)
            error('simulateMIETCurvedMembraneTracking:BadInitialPositions', ...
                'initialPositionsUm must be finite [nMolecules x 2].');
        end
        if any(hypot(initial(:,1), initial(:,2)) > opts.membraneRadiusUm)
            error('simulateMIETCurvedMembraneTracking:BadInitialPositions', ...
                'Every initial position must lie inside the membrane disk.');
        end
        positionsXY(:,:,1) = initial;
    end

    dtSub = opts.dtS / opts.substepsPerFrame;
    for frame = 2:nFrames
        position = positionsXY(:,:,frame-1);
        hitThisFrame = false(nMolecules, 1);
        for substep = 1:opts.substepsPerFrame
            [position, hit] = surfaceBrownianStep(position, ...
                opts.curvaturePerUm, opts.diffusionUm2PerS, dtSub, ...
                opts.membraneRadiusUm);
            hitThisFrame = hitThisFrame | hit;
        end
        positionsXY(:,:,frame) = position;
        boundaryHit(:,frame) = hitThisFrame;
    end

    positionsZ = surfaceHeight(positionsXY, opts.tipHeightUm, ...
        opts.curvaturePerUm);
    lifetimes = opts.lifetimeAtSubstrateNs + ...
        opts.lifetimeSlopeNsPerUm * positionsZ;

    trajectories = struct();
    trajectories.positionsXYUm = positionsXY;
    trajectories.positionsZUm = positionsZ;
    trajectories.positionsXYZUm = cat(2, positionsXY, ...
        reshape(positionsZ, nMolecules, 1, nFrames));
    trajectories.lifetimeNs = lifetimes;
    trajectories.timeS = (0:nFrames-1).' * opts.dtS;
    trajectories.boundaryHit = boundaryHit;
    trajectories.surfaceModel = ...
        'z = tipHeightUm + 0.5*curvaturePerUm*(x^2+y^2)';
    trajectories.diffusionModel = ...
        'Ito diffusion generated by the paraboloid Laplace-Beltrami operator';
end
